const csv = `quarter,revenue,expenses,profit,employees
Q1-2024,1500000,1200000,300000,45
Q2-2024,1800000,1300000,500000,52
Q3-2024,2100000,1400000,700000,58
Q4-2024,2500000,1600000,900000,65
Q1-2025,2800000,1700000,1100000,72
Q2-2025,3200000,1900000,1300000,80`;

const lines = csv.split('\n');
const data = lines.slice(1) // Skip header
    .filter(line => line.trim() !== '') // Remove empty lines
    .map((line, index) => ({
        x: index + 1, // Q1-2024 = 1, Q2-2024 = 2, etc.
        y: parseInt(line.split(',')[1], 10)
    }));

const n = data.length;
const sumX = data.reduce((sum, d) => sum + d.x, 0);
const sumY = data.reduce((sum, d) => sum + d.y, 0);
const sumXY = data.reduce((sum, d) => sum + d.x * d.y, 0);
const sumX2 = data.reduce((sum, d) => sum + d.x * d.x, 0);

const numerator = n * sumXY - sumX * sumY;
const denominator = n * sumX2 - sumX * sumX;
const slope = numerator / denominator;

console.log(slope > 0 ? 'increasing' : 'decreasing');

