// Try to find information about "Small Things Considered" radio program
const axios = require('axios');
const cheerio = require('cheerio');

async function searchSmallThingsConsidered() {
  try {
    // First, let's check if it's an NPR program
    const nprSearch = await axios.get('https://www.npr.org/search?query=Small%20Things%20Considered&searchType=all');
    const $ = cheerio.load(nprSearch.data);
    const results = [];

    // Look for relevant links and information
    $('.item').each((i, el) => {
      const title = $(el).find('.title').text().trim();
      const link = $(el).find('a').attr('href');
      const description = $(el).find('.teaser').text().trim();

      if (title.toLowerCase().includes('small things considered')) {
        results.push({ title, link, description });
      }
    });

    console.log('Found results from NPR search:', results);

    // If no results from NPR, try Wikipedia
    if (results.length === 0) {
      const wikiSearch = await axios.get('https://en.wikipedia.org/w/index.php?search=Small+Things+Considered+radio+program&title=Special%3ASearch');
      const $$ = cheerio.load(wikiSearch.data);

      const wikiResults = [];
      $$('.mw-search-result-heading').each((i, el) => {
        const title = $(el).text().trim();
        const link = 'https://en.wikipedia.org' + $(el).find('a').attr('href');
        wikiResults.push({ title, link });
      });

      console.log('Found results from Wikipedia search:', wikiResults);
    }

  } catch (error) {
    console.error('Error searching for "Small Things Considered":', error);
  }
}

searchSmallThingsConsidered();

// Try to find information about "Small Things Considered" radio program using WolframAlpha
const axios = require('axios');

async function searchWolframAlpha() {
  try {
    // Get information about "Small Things Considered" radio program
    const query = "Small Things Considered radio program producer";
    const encodedQuery = encodeURIComponent(query);
    const response = await axios.get(`https://api.wolframalpha.com/v1/result?i=${encodedQuery}&appid=DEMO`);

    console.log('WolframAlpha response:', response.data);
  } catch (error) {
    console.error('Error querying WolframAlpha:', error);

    if (error.response) {
      console.error('Response data:', error.response.data);
    }
  }
}

searchWolframAlpha();

