import requests
from bs4 import BeautifulSoup

# Try to get information about Mormon religious practices
try:
    mormon_url = "https://en.wikipedia.org/wiki/Mormon_culture"
    response = requests.get(mormon_url, timeout=10)
    if response.status_code == 200:
        soup = BeautifulSoup(response.text, 'html.parser')
        print("Mormon Culture page accessed successfully")

        # Look for sections on religious practices
        practice_sections = []
        for heading in soup.find_all(['h2', 'h3']):
            if 'practice' in heading.text.lower() or 'worship' in heading.text.lower():
                practice_sections.append(heading.text.strip())

        print(f"Found practice-related sections: {practice_sections}")
    else:
        print(f"Failed to access Mormon page: {response.status_code}")
except Exception as e:
    print(f"Error accessing Mormon page: {e}")

# Try to get information about Eastern Christian religious practices
try:
    eastern_url = "https://en.wikipedia.org/wiki/Eastern_Christianity"
    response = requests.get(eastern_url, timeout=10)
    if response.status_code == 200:
        soup = BeautifulSoup(response.text, 'html.parser')
        print("\nEastern Christianity page accessed successfully")

        # Look for sections on religious practices
        practice_sections = []
        for heading in soup.find_all(['h2', 'h3']):
            if 'practice' in heading.text.lower() or 'worship' in heading.text.lower() or 'liturgy' in heading.text.lower():
                practice_sections.append(heading.text.strip())

        print(f"Found practice-related sections: {practice_sections}")
    else:
        print(f"Failed to access Eastern Christianity page: {response.status_code}")
except Exception as e:
    print(f"Error accessing Eastern Christianity page: {e}")

